// The route of a request ({route, params}) or null; the path may carry a query. The first route that fits wins;
// {param} is one non-empty path segment.
export function matchRoute(method, pathWithQuery) {
  let pathname
  try { pathname = decodeURIComponent(String(pathWithQuery).split('?')[0].split('#')[0]) } catch { return null }
  const segs = pathname.split('/')
  for (const route of routes.routes) {
    if (route.method !== method) continue
    const tpl = route.path.split('/')
    if (tpl.length !== segs.length) continue
    const params = {}
    let ok = true
    for (let i = 0; i < tpl.length && ok; i++) {
      const m = /^\{(\w+)\}$/.exec(tpl[i])
      if (m) { if (segs[i] === '') ok = false; else params[m[1]] = segs[i] } else ok = tpl[i] === segs[i]
    }
    if (ok) return { route, params }
  }
  return null
}

// The schema URI an answer with this status must match: responses[status], else responses[<digit>xx], else the error
// schema for any status >= 400; null when the route has no such success status (itself a contract violation).
export function responseSchema(route, status) {
  const s = String(status)
  return route.responses[s] ?? route.responses[`${s[0]}xx`] ?? (status >= 400 ? routes.errors : null)
}
